import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Standard 3D convolution (groups = 1), NCDHW layout, square kernel.
// Cooperative tiled implementation:
//   - blockIdx.z -> batch
//   - blockIdx.y -> tile of CcPerBlock output channels
//   - blockIdx.x -> 3D tile of (TD x TH x TW) output spatial points
// The input activation tile (with halo) for one input channel and the
// matching weight slice are staged in shared memory, one input channel
// at a time, so shared-memory usage is independent of Cin. Each thread
// computes a CVec x PVec register tile of outputs (CVec output
// channels x PVec consecutive points along W) from the staged tiles.
template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Wd,
    int OC, int KD, int KH, int KW,
    int stride, int padding, int dilation,
    int Dout, int Hout, int Wout)
{
  constexpr int Threads    = 256;
  constexpr int CcPerBlock = 16;
  constexpr int CVec       = 4;  // output channels per thread
  constexpr int PVec       = 4;  // output points per thread (along W)
  constexpr int TD         = 4;  // output tile depth  per block
  constexpr int TH         = 8;  // output tile height per block
  constexpr int TW         = 8;  // output tile width  per block
  const int tid   = threadIdx.x;
  const int c_grp = tid & (CVec - 1); // channel lane in [0, CVec)
  const int p_grp = tid / CVec;       // point group   in [0, 64)
  const int n      = blockIdx.z;
  const int c_base = blockIdx.y * CcPerBlock;
  // Decode spatial tile index from blockIdx.x
  const int ntw    = (Wout + TW - 1) / TW;
  const int nth    = (Hout + TH - 1) / TH;
  const int td_idx = blockIdx.x / (nth * ntw);
  const int t_rem  = blockIdx.x - td_idx * (nth * ntw);
  const int th_idx = t_rem / ntw;
  const int tw_idx = t_rem - th_idx * ntw;
  const int od0 = td_idx * TD;
  const int oh0 = th_idx * TH;
  const int ow0 = tw_idx * TW;
  // Thread's local output coordinates (PVec consecutive points along W)
  const int ld  = p_grp / (TH * (TW / PVec));
  const int lh  = (p_grp % (TH * (TW / PVec))) / (TW / PVec);
  const int lw0 = (p_grp % (TW / PVec)) * PVec;
  const int od = od0 + ld;
  const int oh = oh0 + lh;
  // Input tile (with halo) geometry for this block
  const int Id  = (TD - 1) * stride + (KD - 1) * dilation + 1;
  const int Ih  = (TH - 1) * stride + (KH - 1) * dilation + 1;
  const int Iw  = (TW - 1) * stride + (KW - 1) * dilation + 1;
  const int Iwp = Iw + 1; // padded pitch to reduce bank conflicts
  const int idb = od0 * stride - padding;
  const int ihb = oh0 * stride - padding;
  const int iwb = ow0 * stride - padding;
  const int K3 = KD * KH * KW; // kernel elements per input channel
  const int R  = Cin * K3;     // reduction size per output element
  // Global memory strides (int64 to avoid overflow)
  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;
  const int64_t sYn = (int64_t)OC * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  // CuTe global tensors for this batch
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  // Weight: [OC, Cin, KD, KH, KW] contiguous -> [OC, R]
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, R),
      make_stride((int64_t)R, Int<1>{})
  );
  // Shared memory: input tile for one channel + weight slice
  extern __shared__ char smem_raw[];
  T* sX_raw = reinterpret_cast<T*>(smem_raw);
  T* sW_raw = sX_raw + (size_t)Id * Ih * Iwp;
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Id, Ih, Iw),
      make_stride(Ih * Iwp, Iwp, Int<1>{})
  );
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, K3),
      make_stride(K3, Int<1>{})
  );
  // Accumulators, initialized with bias if present
  float acc[CVec][PVec];
  #pragma unroll
  for (int k = 0; k < CVec; ++k) {
    int c = c_base + c_grp + k * CVec;
    float bval = 0.0f;
    if (B != nullptr && c < OC) bval = (float)B[c];
    #pragma unroll
    for (int j = 0; j < PVec; ++j) acc[k][j] = bval;
  }
  const bool dh_ok = (od < Dout) && (oh < Hout);
  const int tile_elems = Id * Ih * Iw;
  const int w_elems    = CcPerBlock * K3;
  const int idl_base = ld  * stride;
  const int ihl_base = lh  * stride;
  const int iwl_base = lw0 * stride;
  // Loop over input channels, staging one channel's tile at a time
  for (int cin = 0; cin < Cin; ++cin) {
    __syncthreads(); // protect reads from previous iteration
    // Stage input activation tile (zero-fill padding region)
    for (int e = tid; e < tile_elems; e += Threads) {
      int iw = e % Iw;
      int t  = e / Iw;
      int ih = t % Ih;
      int id = t / Ih;
      int gid = idb + id;
      int gih = ihb + ih;
      int giw = iwb + iw;
      T v = T(0);
      if ((unsigned)gid < (unsigned)D &&
          (unsigned)gih < (unsigned)H &&
          (unsigned)giw < (unsigned)Wd) {
        v = mX(cin, gid, gih, giw);
      }
      sX(id, ih, iw) = v;
    }
    // Stage this input channel's weight slice for the block's channels
    for (int e = tid; e < w_elems; e += Threads) {
      int cc = e / K3;
      int r2 = e - cc * K3;
      int c  = c_base + cc;
      sW(cc, r2) = (c < OC) ? mW(c, (int64_t)cin * K3 + r2) : T(0);
    }
    __syncthreads();
    // Direct convolution over the staged tile with register blocking
    for (int kd = 0; kd < KD; ++kd) {
      const int idl = idl_base + kd * dilation;
      for (int kh = 0; kh < KH; ++kh) {
        const int ihl = ihl_base + kh * dilation;
        for (int kw = 0; kw < KW; ++kw) {
          const int r2 = (kd * KH + kh) * KW + kw;
          float wv[CVec];
          #pragma unroll
          for (int k = 0; k < CVec; ++k)
            wv[k] = (float)sW(c_grp + k * CVec, r2);
          const int iwl = iwl_base + kw * dilation;
          float xv[PVec];
          #pragma unroll
          for (int j = 0; j < PVec; ++j)
            xv[j] = (float)sX(idl, ihl, iwl + j * stride);
          #pragma unroll
          for (int k = 0; k < CVec; ++k) {
            #pragma unroll
            for (int j = 0; j < PVec; ++j)
              acc[k][j] += xv[j] * wv[k];
          }
        }
      }
    }
  }
  // Store results
  #pragma unroll
  for (int k = 0; k < CVec; ++k) {
    int c = c_base + c_grp + k * CVec;
    if (c >= OC || !dh_ok) continue;
    #pragma unroll
    for (int j = 0; j < PVec; ++j) {
      int ow = ow0 + lw0 + j;
      if (ow < Wout) {
        mY(c, od, oh, ow) = static_cast<T>(acc[k][j]);
      }
    }
  }
}

torch::Tensor conv3d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [OC, Cin, KD, KH, KW] (groups=1)");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Wd  = x.size(4);

  int64_t OC = w.size(0);
  int64_t KD = w.size(2);
  int64_t KH = w.size(3);
  int64_t KW = w.size(4);

  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1)");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Dout = (D + 2 * padding - dilation * (KD - 1) - 1) / stride + 1;
  int64_t Hout = (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  int64_t Wout = (Wd + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Dout, Hout, Wout}, x.options());

  constexpr int Threads    = 256;
  constexpr int CcPerBlock = 16;
  constexpr int TD = 4, TH = 8, TW = 8;
  const int64_t K3 = KD * KH * KW;
  const int64_t Id = (int64_t)(TD - 1) * stride + (KD - 1) * dilation + 1;
  const int64_t Ih = (int64_t)(TH - 1) * stride + (KH - 1) * dilation + 1;
  const int64_t Iw = (int64_t)(TW - 1) * stride + (KW - 1) * dilation + 1;
  const int64_t tiles_d = (Dout + TD - 1) / TD;
  const int64_t tiles_h = (Hout + TH - 1) / TH;
  const int64_t tiles_w = (Wout + TW - 1) / TW;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(tiles_d * tiles_h * tiles_w),
      (unsigned)((OC + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );
  size_t smem_bytes = ((size_t)Id * Ih * (Iw + 1) +
                       (size_t)CcPerBlock * K3) * sizeof(float);
  if (smem_bytes > 48 * 1024) {
    static size_t configured_smem = 48 * 1024;
    if (smem_bytes > configured_smem) {
      cudaFuncSetAttribute(conv3d_kernel<float>,
                           cudaFuncAttributeMaxDynamicSharedMemorySize,
                           (int)smem_bytes);
      configured_smem = smem_bytes;
    }
  }
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
      (int)OC, (int)KD, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (groups=1) implemented with a single custom
    CUDA kernel written with CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        assert groups == 1, "ModelNew supports groups=1 only"
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert stride >= 1 and padding >= 0 and dilation >= 1

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size ** 3
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

